import pytest

from numeric import moving_average


def test_moving_average_single_element():
    assert moving_average([5], 1) == [5.0]


def test_moving_average_full_window():
    assert moving_average([1, 2, 3, 4, 5], 5) == [3.0]


def test_moving_average_window_equals_length():
    assert moving_average([10, 20, 30], 3) == [20.0]


def test_moving_average_empty_input():
    assert moving_average([], 1) == []


def test_moving_average_window_too_small():
    with pytest.raises(ValueError, match="window must be >= 1"):
        moving_average([1, 2, 3], 0)


def test_moving_average_window_too_large():
    with pytest.raises(ValueError, match="window larger than data"):
        moving_average([1, 2], 3)


def test_moving_average_float_values():
    assert moving_average([1.5, 2.5, 3.5], 2) == [2.0, 3.0]


def test_moving_average_zero_window():
    with pytest.raises(ValueError, match="window must be >= 1"):
        moving_average([1, 2, 3], -1)

