from validators import validate_port


def test_validate_port_accepts_boundary_values():
    """Test that both 1 and 65535 are accepted (boundary cases)."""
    assert validate_port(1) == 1
    assert validate_port(65535) == 65535


def test_validate_port_rejects_bool_and_non_integer():
    """Test that both bool and non-integer inputs raise ValueError."""
    for invalid_input in [True, False, "123", 123.45, None]:
        with pytest.raises(ValueError, match="port must be an integer"):
            validate_port(invalid_input)


def test_validate_port_rejects_out_of_range():
    """Test that ports outside 1..65535 raise ValueError."""
    for invalid_port in [0, 65536, -1, 65537]:
        with pytest.raises(ValueError, match="port out of range"):
            validate_port(invalid_port)


def test_validate_port_returns_input_unchanged():
    """Test that valid ports are returned unchanged."""
    valid_ports = [1, 100, 1024, 32768, 65535]
    for port in valid_ports:
        assert validate_port(port) == port


